use super::*;
use crate::runner_host::query_snapshot::SourceSnapshot;
type Error=Box<dyn std::error::Error>;

fn prepare(f:&Fixture,stage:crate::GeneratorName,admitted:crate::GeneratorName)->Result<SourceSnapshot,Error>{
 let request=crate::policy_request::WorkspacePolicyRequest{root:f.workspace.root().to_owned(),recursive_roots:f.workspace.recursive_roots().to_vec(),configuration:f.workspace.configuration().0.to_owned()};
 let intent=|name|{let mut intent=PolicyInputRequest::default();intent.workspace=Some(request.clone());intent.workspace_generators=vec![name];intent.admit().unwrap()};let staged=intent(stage);let admitted=intent(admitted);
 let state=Arc::new(Mutex::new(QueryState::default()));let mut attempt=QueryAttempt::new(Arc::clone(&state),true);
 attempt.capture_with_workspace_generator_recorded_sources(&f._front,Arc::clone(&f.queries),Arc::clone(&f.workspace),&request,&f.inputs,&staged)?;
 let receipt=crate::request_runner::runner_freshness::admit_generator_workspace_captured(&f.inputs,None,&crate::frozen_inputs::Inputs::Live,&Default::default(),Arc::clone(&f.workspace),&admitted)?;
 attempt.admit_workspace_policy(receipt)?;attempt.finish_analyzed();let snapshot=state.lock().unwrap().snapshot.take().unwrap();Ok(snapshot)
}

#[test]fn generation_retirement_keeps_actual_freshness_metadata_without_retaining_workspace_or_scope(){
 let f=Fixture::new_generator();let snapshot=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap();let workspace=Arc::downgrade(&f.workspace);
 let inputs=snapshot.retire_for_generation().unwrap();inputs.require_current(&FileSystemInputs).unwrap();drop(f);assert!(workspace.upgrade().is_none(),"only complete input metadata may survive retiring the real snapshot");inputs.require_current(&FileSystemInputs).unwrap();
}
#[test]fn generation_retirement_refuses_unissued_and_mismatched_question_closures(){
 let f=Fixture::new_generator();assert!(prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Reads).is_err());let snapshot=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap();snapshot.retire_for_generation().unwrap().require_current(&FileSystemInputs).unwrap();assert!(f._snapshot.retire_for_generation().is_err(),"ordinary read-only workspace admission carries no generation closure");
}
#[test]fn generation_closure_preserves_recorded_negative_and_changed_source_refusals(){
 let f=Fixture::new_generator();let snapshot=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap();let inputs=snapshot.retire_for_generation().unwrap();inputs.require_current(&FileSystemInputs).unwrap();std::fs::write(f.root.join("missing.toml"),"# appeared after source publication\n").unwrap();assert!(inputs.require_current(&FileSystemInputs).is_err(),"a recorded optional absence must still invalidate the generation commit");
}
#[test]fn generation_closure_is_the_complete_final_barrier_including_late_recorded_inputs(){
 let mut f=Fixture::new_generator();let late=f.root.join("late-generation-input.txt");std::fs::write(&late,"before").unwrap();f.change_uncompiled_marker();
 let request=crate::policy_request::WorkspacePolicyRequest{root:f.workspace.root().to_owned(),recursive_roots:f.workspace.recursive_roots().to_vec(),configuration:f.workspace.configuration().0.to_owned()};let mut intent=PolicyInputRequest::default();intent.workspace=Some(request.clone());intent.workspace_generators=vec![crate::GeneratorName::Deps];let intent=intent.admit().unwrap();let state=Arc::new(Mutex::new(QueryState::default()));let mut attempt=QueryAttempt::new(Arc::clone(&state),true);attempt.capture_with_workspace_generator_recorded_sources(&f._front,Arc::clone(&f.queries),Arc::clone(&f.workspace),&request,&f.inputs,&intent).unwrap();
 f.inputs.read_binary(&late).unwrap();let receipt=crate::request_runner::runner_freshness::admit_generator_workspace_captured(&f.inputs,None,&crate::frozen_inputs::Inputs::Live,&Default::default(),Arc::clone(&f.workspace),&intent).unwrap();attempt.admit_workspace_policy(receipt).unwrap();attempt.finish_analyzed();let snapshot=state.lock().unwrap().snapshot.take().unwrap();let inputs=snapshot.retire_for_generation().unwrap();inputs.require_current(&FileSystemInputs).unwrap();std::fs::write(&late,"changed with a different length after staging").unwrap();assert!(inputs.require_current(&FileSystemInputs).is_err(),"final admission facts beyond the staged subset must be retained");
}
#[test]fn generation_closure_preserves_real_provider_io_without_semantic_refusal_or_retry(){
 struct Fault;impl SnapshotProvider for Fault{fn stamp(&self,_:&Path)->io::Result<Stamp>{Err(io::Error::from_raw_os_error(1450))}fn read(&self,_:&Path)->io::Result<(Stamp,Vec<u8>)>{Err(io::Error::from_raw_os_error(1450))}fn list(&self,_:&Path)->io::Result<FolderListing>{Err(io::Error::from_raw_os_error(1450))}}
 let f=Fixture::new_generator();let inputs=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap().retire_for_generation().unwrap();let error=inputs.require_current(&Fault).err().unwrap();assert_eq!(error.downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));inputs.require_current(&FileSystemInputs).unwrap();
}

#[test]fn generation_staging_uses_actual_selected_artifact_then_retires_snapshot_without_source_writes(){
 let f=Fixture::new_generator();let snapshot=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap();
 let expected={let guard=snapshot.workspace_native_read().unwrap();let child=snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap();f.queries.with_workspace_generator_guard(&f.workspace,&guard,child,crate::GeneratorName::Deps,|artifact|Ok(artifact.text().to_owned())).unwrap()};
 let reads=f.reads.load(Ordering::Relaxed);let computed=f.queries.db.stats(generator_policy::GENERATOR_RESULT).computed;let workspace=Arc::downgrade(&f.workspace);
 let scratch=crate::test_scratch::dir("generation-actual-stage");let spool=crate::generation_staging::temporary_output(&scratch).unwrap();let mut closed=snapshot.stage_generation(spool).unwrap();assert!(!closed.included()[0],"actual captured root manifest does not include deps output");assert_eq!(f.reads.load(Ordering::Relaxed),reads);assert_eq!(f.queries.db.stats(generator_policy::GENERATOR_RESULT).computed,computed);assert!(!f.root.join("code/engine/_generated/deps.dm").exists());
 let mut rows=Vec::new();closed.journal.visit(&mut |_|Ok(()),&mut|kind,line,path,_,body|{let mut text=String::new();body.read_to_string(&mut text)?;rows.push((kind,line,path.to_owned(),text));Ok(())}).unwrap();assert_eq!(rows,vec![(3,0,"deps".into(),"".into()),(1,0,"code/engine/_generated/deps.dm".into(),expected)]);closed.inputs.require_current(&FileSystemInputs).unwrap();drop(f);assert!(workspace.upgrade().is_none(),"sealed output/freshness metadata must not retain a semantic source owner");closed.inputs.require_current(&FileSystemInputs).unwrap();
}
#[test]fn generation_staging_rejects_unissued_closure_before_source_jobs(){
 let f=Fixture::new_generator();let computed=f.queries.db.stats(generator_policy::GENERATOR_RESULT).computed;let scratch=crate::test_scratch::dir("generation-unissued-stage");let spool=crate::generation_staging::temporary_output(&scratch).unwrap();assert!(f._snapshot.stage_generation(spool).is_err());assert_eq!(f.queries.db.stats(generator_policy::GENERATOR_RESULT).computed,computed);assert!(!f.root.join("code/engine/_generated/deps.dm").exists());
}
#[test]fn generation_staging_real_body_io_discards_spool_and_retries_without_installing_a_prefix(){
 let f=Fixture::new_generator();let snapshot=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap();let scratch=crate::test_scratch::dir("generation-stage-body-io");let failure=f.queries.fail_body_syntax_after_for_test(0,io::Error::from_raw_os_error(1450));let error=snapshot.stage_generation(crate::generation_staging::temporary_output(&scratch).unwrap()).err().unwrap();assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(std::fs::read_dir(&scratch).unwrap().count(),0,"failed operation's own anonymous spool is closed");assert!(!f.root.join("code/engine/_generated/deps.dm").exists());drop(failure);let mut healthy=prepare(&f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap().stage_generation(crate::generation_staging::temporary_output(&scratch).unwrap()).unwrap();healthy.journal.verify().unwrap();healthy.inputs.require_current(&FileSystemInputs).unwrap();assert!(!f.root.join("code/engine/_generated/deps.dm").exists());
}

fn transaction_stage(f:&Fixture,label:&str)->(crate::runner_host::query_snapshot::ClosedGeneration,PathBuf){let cache=crate::test_scratch::dir(label);let closed=prepare(f,crate::GeneratorName::Deps,crate::GeneratorName::Deps).unwrap().stage_generation(crate::generation_staging::temporary_output(&cache).unwrap()).unwrap();(closed,cache)}
#[test]fn generation_transaction_final_input_drift_refuses_before_first_output_mutation(){use crate::generation_transaction::{self as tx,Event,Mode};let f=Fixture::new_generator();let(closed,cache)=transaction_stage(&f,"generation-transaction-drift");let target=f.root.join("code/engine/_generated/deps.dm");let error=tx::commit_using(closed,&cache,Mode::Write,&mut|event|{if matches!(event,Event::BeforeFinalFreshness){std::fs::write(f.root.join("code/probe.dm"),"// changed before commit barrier\n")?}Ok(())}).err().unwrap();assert!(error.rollback.is_empty());assert!(!target.exists());assert!(!target.parent().unwrap().exists());}
#[test]fn generation_transaction_rolls_back_missing_output_and_owned_directories_after_first_replacement(){use crate::generation_transaction::{self as tx,Event,Mode};let f=Fixture::new_generator();let(closed,cache)=transaction_stage(&f,"generation-transaction-missing");let target=f.root.join("code/engine/_generated/deps.dm");let error=tx::commit_using(closed,&cache,Mode::Write,&mut|event|if matches!(event,Event::AfterReplacement(0)){Err(io::Error::from_raw_os_error(1450))}else{Ok(())}).err().unwrap();assert_eq!(error.primary.downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));assert!(error.rollback.is_empty(),"{error}");assert!(!target.exists());assert!(!target.parent().unwrap().exists());}
#[test]fn generation_transaction_restores_previous_exact_bytes_and_reports_rollback_failures(){use crate::generation_transaction::{self as tx,Event,Mode};let mut f=Fixture::new_generator();let target=f.root.join("code/engine/_generated/deps.dm");std::fs::create_dir_all(target.parent().unwrap()).unwrap();let old=b"// prior generated output\r\n";std::fs::write(&target,old).unwrap();f.change_uncompiled_marker();let(closed,cache)=transaction_stage(&f,"generation-transaction-restore");let error=tx::commit_using(closed,&cache,Mode::Write,&mut|event|if matches!(event,Event::AfterReplacement(0)){Err(io::Error::from_raw_os_error(1450))}else{Ok(())}).err().unwrap();assert!(error.rollback.is_empty(),"{error}");assert_eq!(std::fs::read(&target).unwrap(),old);f.change_uncompiled_marker();let(closed,cache)=transaction_stage(&f,"generation-transaction-rollback-error");let error=tx::commit_using(closed,&cache,Mode::Write,&mut|event|match event{Event::AfterReplacement(0)=>Err(io::Error::from_raw_os_error(1450)),Event::BeforeRollback(0)=>Err(io::Error::from_raw_os_error(112)),_=>Ok(())}).err().unwrap();assert_eq!(error.primary.downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));assert_eq!(error.rollback[0].error.raw_os_error(),Some(112));assert!(error.to_string().contains("rollback failed"));}
#[test]fn generation_transaction_never_clobbers_external_destination_replacement_during_rollback(){use crate::generation_transaction::{self as tx,Event,Mode};let f=Fixture::new_generator();let(closed,cache)=transaction_stage(&f,"generation-transaction-external");let target=f.root.join("code/engine/_generated/deps.dm");let external=b"// external editor replacement must survive rollback\n";let error=tx::commit_using(closed,&cache,Mode::Write,&mut|event|{if matches!(event,Event::AfterReplacement(0)){std::fs::write(&target,external)?;return Err(io::Error::from_raw_os_error(1450))}Ok(())}).err().unwrap();assert!(!error.rollback.is_empty());assert!(error.rollback.iter().any(|row|row.error.to_string().contains("externally replaced")));assert_eq!(std::fs::read(&target).unwrap(),external);}
#[test]fn generation_transaction_panic_after_replacement_restores_missing_output_without_publishing_state(){use crate::generation_transaction::{self as tx,Event,Mode};let f=Fixture::new_generator();let(closed,cache)=transaction_stage(&f,"generation-transaction-panic");let target=f.root.join("code/engine/_generated/deps.dm");let error=tx::commit_using(closed,&cache,Mode::Write,&mut|event|{if matches!(event,Event::AfterReplacement(0)){panic!("actual installer observer panic")}Ok(())}).err().unwrap();assert!(error.primary.to_string().contains("panicked"));assert!(error.rollback.is_empty(),"{error}");assert!(!target.exists());}

#[test]fn generation_transaction_committed_cleanup_warning_preserves_installed_outputs_and_foreign_backup_replacement(){use crate::generation_transaction::{self as tx,Event,Mode};let mut f=Fixture::new_generator();let target=f.root.join("code/engine/_generated/deps.dm");std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(&target,"// prior output\n").unwrap();f.change_uncompiled_marker();let(closed,cache)=transaction_stage(&f,"generation-transaction-cleanup-warning");let mut foreign=None;let report=tx::commit_using(closed,&cache,Mode::Write,&mut|event|{if matches!(event,Event::AfterCommit){let path=std::fs::read_dir(target.parent().unwrap())?.map(|row|row.map(|row|row.path())).collect::<io::Result<Vec<_>>>()?.into_iter().find(|p|p.file_name().unwrap().to_string_lossy().starts_with(".dmbd-generation-")).expect("actual prewritten restoration payload");std::fs::remove_file(&path)?;std::fs::write(&path,"external replacement of rollback backup must survive")?;foreign=Some(path);return Err(io::Error::from_raw_os_error(112))}Ok(())}).unwrap();assert!(!report.changed.is_empty());assert_eq!(report.cleanup[0].error.raw_os_error(),Some(112));assert!(report.cleanup.iter().any(|row|row.error.to_string().contains("replaced")));assert_ne!(std::fs::read(&target).unwrap(),b"// prior output\n");assert_eq!(std::fs::read(foreign.unwrap()).unwrap(),b"external replacement of rollback backup must survive");}
